import { useState } from 'react'
import { ChevronDown, ChevronRight, Plus, Trash2 } from 'lucide-react'
import { Toggle } from './ui.jsx'

/**
 * Renders a configuration form from a model's JSON Schema (generated by Pydantic),
 * so new models get a settings UI without frontend changes.
 * Supports: enum (select), boolean (switch), number/integer (slider + input),
 * string, nested objects ($ref, collapsible) and arrays of objects (row editor).
 */
export default function SchemaForm({ schema, value, onChange, disabled }) {
  if (!schema?.properties) return null
  return (
    <ObjectFields root={schema} schema={schema} value={value || {}} onChange={onChange} disabled={disabled} />
  )
}

function resolve(root, s) {
  if (!s) return s
  const ref = s.$ref || s.allOf?.[0]?.$ref
  if (ref) {
    const name = ref.split('/').pop()
    return { ...root.$defs?.[name], ...s, $ref: undefined, allOf: undefined }
  }
  return s
}

const humanize = (key) => key.replace(/_/g, ' ').replace(/^\w/, (c) => c.toUpperCase())

function ObjectFields({ root, schema, value, onChange, disabled }) {
  const entries = Object.entries(schema.properties || {})
  const simple = entries.filter(([, s]) => resolve(root, s).type !== 'object')
  const nested = entries.filter(([, s]) => resolve(root, s).type === 'object')
  const set = (key, v) => onChange({ ...value, [key]: v })
  return (
    <div className="space-y-4">
      {simple.map(([key, s]) => (
        <Field key={key} name={key} root={root} schema={resolve(root, s)} value={value[key]}
               onChange={(v) => set(key, v)} disabled={disabled} />
      ))}
      {nested.map(([key, s]) => (
        <NestedGroup key={key} name={key} root={root} schema={resolve(root, s)} value={value[key] || {}}
                     onChange={(v) => set(key, v)} disabled={disabled} />
      ))}
    </div>
  )
}

function NestedGroup({ name, root, schema, value, onChange, disabled }) {
  const [open, setOpen] = useState(false)
  return (
    <div className="rounded-lg border border-slate-200 dark:border-slate-800">
      <button type="button" onClick={() => setOpen(!open)}
              className="flex w-full items-center gap-2 px-3 py-2 text-left text-sm font-medium">
        {open ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
        Advanced: {humanize(name)}
      </button>
      {open && (
        <div className="border-t border-slate-200 p-3 dark:border-slate-800">
          {schema.description && <p className="mb-3 text-xs muted">{schema.description}</p>}
          <ObjectFields root={root} schema={schema} value={value} onChange={onChange} disabled={disabled} />
        </div>
      )}
    </div>
  )
}

function FieldLabel({ name, schema, children }) {
  return (
    <div>
      <div className="flex items-baseline justify-between gap-3">
        <span className="label">{schema.title || humanize(name)}</span>
        {children}
      </div>
      {schema.description && <p className="mt-0.5 text-xs muted">{schema.description}</p>}
    </div>
  )
}

function Field({ name, root, schema, value, onChange, disabled }) {
  const id = `f-${name}`
  if (schema.enum) {
    // Keep the option's original type (e.g. 960, not "960") - <select> only yields strings.
    const pick = (raw) => schema.enum.find((opt) => String(opt) === raw) ?? raw
    return (
      <div className="space-y-1.5">
        <FieldLabel name={name} schema={schema} />
        <select id={id} className="input" value={value ?? schema.default} disabled={disabled}
                onChange={(e) => onChange(pick(e.target.value))}>
          {schema.enum.map((opt) => <option key={opt} value={opt}>{opt}</option>)}
        </select>
      </div>
    )
  }
  if (schema.type === 'boolean') {
    return (
      <Toggle checked={!!value} onChange={onChange} disabled={disabled}
              label={schema.title || humanize(name)} description={schema.description} />
    )
  }
  if (schema.type === 'number' || schema.type === 'integer') {
    return <NumberField name={name} schema={schema} value={value} onChange={onChange} disabled={disabled} />
  }
  if (schema.type === 'array') {
    const items = resolve(root, schema.items)
    if (items?.type === 'object') {
      return <ObjectList name={name} schema={schema} items={items} value={value || []} onChange={onChange}
                         disabled={disabled} />
    }
  }
  return (
    <div className="space-y-1.5">
      <FieldLabel name={name} schema={schema} />
      <input id={id} className="input" value={value ?? ''} disabled={disabled}
             onChange={(e) => onChange(e.target.value)} />
    </div>
  )
}

function NumberField({ name, schema, value, onChange, disabled }) {
  const integer = schema.type === 'integer'
  const min = schema.minimum ?? schema.exclusiveMinimum
  const max = schema.maximum ?? schema.exclusiveMaximum
  const step = schema.multipleOf || (integer ? 1 : max != null && min != null && max - min <= 2 ? 0.01 : 0.1)
  const [text, setText] = useState(null) // free typing; committed on blur
  const commit = (raw) => {
    let v = Number(raw)
    if (!Number.isFinite(v)) return
    if (integer) v = Math.round(v)
    if (schema.multipleOf) v = Math.round(v / schema.multipleOf) * schema.multipleOf
    if (min != null) v = Math.max(min, v)
    if (max != null) v = Math.min(max, v)
    onChange(v)
  }
  const current = value ?? schema.default
  return (
    <div className="space-y-1.5">
      <FieldLabel name={name} schema={schema}>
        <input
          type="number" className="input w-24 py-1 text-right tabular-nums" disabled={disabled} step={step}
          value={text ?? current ?? ''} onChange={(e) => setText(e.target.value)}
          onBlur={() => { if (text != null) commit(text); setText(null) }}
          onKeyDown={(e) => { if (e.key === 'Enter') e.currentTarget.blur() }}
        />
      </FieldLabel>
      {min != null && max != null && (
        <input type="range" className="w-full" min={min} max={max} step={step} disabled={disabled}
               value={current ?? min} onChange={(e) => commit(e.target.value)} aria-label={name} />
      )}
    </div>
  )
}

function ObjectList({ name, schema, items, value, onChange, disabled }) {
  const keys = Object.keys(items.properties || {})
  const update = (i, key, v) => onChange(value.map((row, j) => (j === i ? { ...row, [key]: v } : row)))
  return (
    <div className="space-y-2">
      <FieldLabel name={name} schema={schema} />
      <div className="overflow-hidden rounded-lg border border-slate-200 dark:border-slate-800">
        <div className="grid gap-2 bg-slate-50 px-3 py-1.5 text-xs font-medium muted dark:bg-slate-800/50"
             style={{ gridTemplateColumns: `${keys.map((k) => (k === 'prompt' ? '2fr' : '1fr')).join(' ')} 2rem` }}>
          {keys.map((k) => <span key={k}>{items.properties[k].title || humanize(k)}</span>)}
          <span />
        </div>
        {value.map((row, i) => (
          <div key={i} className="grid items-center gap-2 border-t border-slate-200 px-3 py-1.5 dark:border-slate-800"
               style={{ gridTemplateColumns: `${keys.map((k) => (k === 'prompt' ? '2fr' : '1fr')).join(' ')} 2rem` }}>
            {keys.map((k) => (
              <input key={k} className="input py-1" value={row[k] ?? ''} disabled={disabled}
                     aria-label={`${k} ${i + 1}`} onChange={(e) => update(i, k, e.target.value)} />
            ))}
            <button type="button" className="btn-ghost p-1" disabled={disabled} aria-label="Remove row"
                    onClick={() => onChange(value.filter((_, j) => j !== i))}>
              <Trash2 className="h-4 w-4" />
            </button>
          </div>
        ))}
      </div>
      <button type="button" className="btn-ghost px-2 py-1 text-xs" disabled={disabled}
              onClick={() => onChange([...value, Object.fromEntries(keys.map((k) => [k, '']))])}>
        <Plus className="h-3.5 w-3.5" /> Add row
      </button>
    </div>
  )
}
